test('lineTotal multiplies qty by unitPrice', () => {
  assert.equal(lineTotal({ qty: 1, unitPrice: 9500 }), 9500);
  assert.equal(lineTotal({ qty: 10, unitPrice: 9500 }), 95000);
  assert.equal(lineTotal({ qty: 1, unitPrice: 120000 }), 120000);
});

test('lineTotal works with zero quantity', () => {
  assert.equal(lineTotal({ qty: 0, unitPrice: 9500 }), 0);
});

test('invoiceTotals calculates correct subtotal and total', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 9500 },
      { qty: 1, unitPrice: 120000 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 95000 + 120000);
  assert.equal(totals.total, 215000);
});

test('invoiceTotals works with empty lines array', () => {
  const invoice = { lines: [] };
  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals works with single line', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 6000 }],
  };

  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 30000);
  assert.equal(totals.total, 30000);
});

test('invoiceTotals with created invoice', () => {
